import{polygonLength}from"d3-polygon";import{distance,pointAlong}from"./math.js";function addPoints(t,n){var o=t.length+n,e=polygonLength(t)/n;let i=0,l=0,g=e/2;for(;t.length<o;){var p=t[i],s=t[(i+1)%t.length],c=distance(p,s);g<=l+c?(t.splice(i+1,0,c?pointAlong(p,s,(g-l)/c):p.slice(0)),g+=e):(l+=c,i++)}}function bisect(e,i=1/0){for(let o=0;o<e.length;o++){let t=e[o],n=o===e.length-1?e[0]:e[o+1];for(;distance(t,n)>i;)n=pointAlong(t,n,.5),e.splice(o+1,0,n)}}export{addPoints,bisect};